import re
from datetime import datetime

_GMAIL_DOMAINS = {"gmail.com", "googlemail.com"}
_DATE_FORMATS = ("%Y-%m-%dT%H:%M:%S", "%Y-%m-%d", "%m/%d/%Y")


def _s(value):
    return "" if value is None else str(value)


def _normalize_email(raw):
    """Return the normalized email if valid, else ''."""
    s = _s(raw)
    m = re.search(r"<([^<>]*)>", s)
    if m:
        s = m.group(1)
    s = s.strip().lower()
    if s.count("@") != 1:
        return ""
    local, domain = s.split("@")
    if domain in _GMAIL_DOMAINS:
        local = local.replace(".", "")
        local = local.split("+", 1)[0]
        domain = "gmail.com"
    if not local:
        return ""
    if "." not in domain or domain.startswith(".") or domain.endswith("."):
        return ""
    return local + "@" + domain


def _normalize_phone(raw):
    """Return 10-digit phone if valid, else ''."""
    s = _s(raw)
    m = re.search(r"ext|x|#", s, re.IGNORECASE)
    if m:
        s = s[:m.start()]
    digits = re.sub(r"[^0-9]", "", s)
    if len(digits) == 11 and digits[0] == "1":
        digits = digits[1:]
    if len(digits) == 10 and digits[0] not in "01":
        return digits
    return ""


def _normalize_zip(raw):
    z = _s(raw).strip()
    if re.fullmatch(r"[0-9]{5}-[0-9]{4}", z):
        z = z.split("-")[0]
    if re.fullmatch(r"[0-9]{4}", z):
        z = "0" + z
    if not re.fullmatch(r"[0-9]{5}", z):
        return ""
    return z


def _normalize_name(raw):
    n = _s(raw).strip()
    if n.isupper() or n.islower():
        n = n.title()
    return n


def _parse_updated(raw):
    s = _s(raw).strip()
    for fmt in _DATE_FORMATS:
        try:
            return datetime.strptime(s, fmt)
        except ValueError:
            continue
    raise ValueError("Unrecognized date format in 'updated': %r" % (raw,))


def _parse_tags(raw):
    out = set()
    for t in re.split(r"[;,]", _s(raw)):
        t = t.strip().lower()
        if t:
            out.add(t)
    return out


def dedupe_contacts(rows):
    # ---- Normalize and filter ----
    recs = []
    for row in rows:
        email = _normalize_email(row.get("email"))
        phone = _normalize_phone(row.get("phone"))
        if not email and not phone:
            continue
        source = _s(row.get("source")).strip().lower()
        recs.append({
            "first_name": _normalize_name(row.get("first_name")),
            "last_name": _normalize_name(row.get("last_name")),
            "email": email,
            "phone": phone,
            "zip": _normalize_zip(row.get("zip")),
            "source": source,
            "manual": source == "manual",
            "tags": _parse_tags(row.get("tags")),
            "opted_out": _s(row.get("opted_out")).strip().lower()
                         in ("y", "yes", "true", "1"),
            "updated": _parse_updated(row.get("updated")),
        })

    n = len(recs)

    # ---- Union-find ----
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            if ra < rb:
                parent[rb] = ra
            else:
                parent[ra] = rb

    email_seen = {}
    phone_last_seen = {}
    for i, r in enumerate(recs):
        if r["email"]:
            if r["email"] in email_seen:
                union(i, email_seen[r["email"]])
            else:
                email_seen[r["email"]] = i
        last = r["last_name"].lower()
        if r["phone"] and last:
            key = (r["phone"], last)
            if key in phone_last_seen:
                union(i, phone_last_seen[key])
            else:
                phone_last_seen[key] = i

    groups = {}
    for i in range(n):
        groups.setdefault(find(i), []).append(i)

    # ---- Build output ----
    def pick(indices, field):
        cands = [i for i in indices if recs[i][field]]
        if not cands:
            return None
        # indices already ascending; stable sorts keep input order as final tiebreak
        cands.sort(key=lambda i: recs[i]["updated"], reverse=True)
        cands.sort(key=lambda i: 0 if recs[i]["manual"] else 1)
        return recs[cands[0]]

    result = []
    for indices in sorted(groups.values(), key=lambda g: g[0]):
        out = {}
        for field in ("first_name", "last_name", "zip", "email", "phone", "source"):
            best = pick(indices, field)
            out[field] = best[field] if best else ""
        tags = set()
        for i in indices:
            tags |= recs[i]["tags"]
        out["tags"] = ";".join(sorted(tags))
        out["opted_out"] = "Y" if any(recs[i]["opted_out"] for i in indices) else "N"
        out["updated"] = max(recs[i]["updated"] for i in indices).strftime("%Y-%m-%d")
        result.append(out)

    return result
